"""Rotary embedding dispatch — direct call into _pybridge."""

from dataclasses import dataclass

import torch
from kestrel_kernels._pybridge import rotary_embedding as _raw
from kestrel_kernels.fallback import should_use_cuda_impl
from kestrel_kernels.rotary_embedding_ops.fallback import rotary_embedding_torch

_SUPPORTED_SMS = {80, 86, 87, 89, 90, 100, 110, 120}


@dataclass(frozen=True)
class PreparedNeoXRotary:
    """Per-token NeoX cos/sin data prepared once for repeated Q/K applies."""

    cos: torch.Tensor
    sin: torch.Tensor
    positions: torch.Tensor
    cache: torch.Tensor


def rotary_embedding(positions, query, key, head_size, cos_sin_cache):
    if not should_use_cuda_impl(
        device=query.device,
        kernel_key="rotary_embedding",
        op_name="rotary_embedding",
        supported_sms=_SUPPORTED_SMS,
    ):
        rotary_embedding_torch(positions, query, key, head_size, cos_sin_cache)
        return
    _raw(positions, query, key, head_size, cos_sin_cache)


def prepare_neox_rotary(
    cos: torch.Tensor,
    sin: torch.Tensor,
) -> PreparedNeoXRotary:
    """Prepare selected per-token cos/sin rows for the indexed native ABI."""

    if cos.shape != sin.shape:
        raise ValueError("cos and sin must have matching shapes")
    if cos.ndim < 2 or int(cos.shape[-1]) % 2:
        raise ValueError("cos and sin must end in an even rotary dimension")
    rotary_dim = int(cos.shape[-1])
    half = rotary_dim // 2
    token_shape = tuple(map(int, cos.shape[:-1]))
    positions = torch.arange(
        cos.numel() // rotary_dim,
        dtype=torch.long,
        device=cos.device,
    ).reshape(token_shape)
    cache = (
        torch.cat((cos[..., :half], sin[..., :half]), dim=-1)
        .reshape(-1, rotary_dim)
        .float()
        .contiguous()
    )
    return PreparedNeoXRotary(
        cos=cos,
        sin=sin,
        positions=positions,
        cache=cache,
    )


def _rotate_half(x: torch.Tensor) -> torch.Tensor:
    half = int(x.shape[-1]) // 2
    return torch.cat((-x[..., half:], x[..., :half]), dim=-1)


def _apply_neox_reference(
    value: torch.Tensor,
    prepared: PreparedNeoXRotary,
) -> torch.Tensor:
    rotary_dim = int(prepared.cos.shape[-1])
    rotated = value[..., :rotary_dim]
    cos = prepared.cos.unsqueeze(-2)
    sin = prepared.sin.unsqueeze(-2)
    result = (rotated * cos) + (_rotate_half(rotated) * sin)
    if rotary_dim == int(value.shape[-1]):
        return result
    return torch.cat((result, value[..., rotary_dim:]), dim=-1)


def apply_neox_rotary(
    query: torch.Tensor,
    key: torch.Tensor | None,
    prepared: PreparedNeoXRotary,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Apply prepared NeoX rotary to BSHD query/key tensors."""

    native = (
        query.is_cuda
        and query.dtype is torch.bfloat16
        and (
            key is None
            or (key.is_cuda and key.dtype is torch.bfloat16)
        )
    )
    if native:
        key_target = key if key is not None else query[..., :0, :]
        rotary_embedding(
            prepared.positions,
            query,
            key_target,
            int(query.shape[-1]),
            prepared.cache,
        )
        return query, key
    query = _apply_neox_reference(query, prepared)
    if key is not None:
        key = _apply_neox_reference(key, prepared)
    return query, key


__all__ = [
    "PreparedNeoXRotary",
    "apply_neox_rotary",
    "prepare_neox_rotary",
    "rotary_embedding",
]
